-- Database: candidate_sdb
-- Source-derived baseline; connect to the existing named database before running.
-- Fresh empty public schema only. No DROP, ALTER existing data, CREATE DATABASE or seed data.
-- Do not execute against existing tables without review; CREATE TABLE intentionally fails on collisions.
-- UUID IDs generated by Hibernate; IDENTITY maps to GENERATED BY DEFAULT AS IDENTITY.
-- No cross-service FK, SQL defaults for Java values, triggers or ON DELETE CASCADE.
BEGIN;
SET LOCAL search_path = public;

-- Entity source: ats_parrent/services/candidate-service/src/main/java/fu/ats/infrastructure/persistence/entity/CandidateEntity.java
-- Unique backing index ux_candidates_user_id: @Table.indexes trong CandidateEntity.java
CREATE TABLE candidates (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    user_id UUID NOT NULL,
    full_name VARCHAR(255),
    status VARCHAR(50),
    source VARCHAR(150),
    utm_source VARCHAR(150),
    utm_medium VARCHAR(150),
    utm_campaign VARCHAR(255),
    is_duplicate BOOLEAN NOT NULL,
    cv_file_id BIGINT,
    parsed_cv_data JSONB,
    CONSTRAINT pk_candidates PRIMARY KEY (id),
    CONSTRAINT ux_candidates_user_id UNIQUE (user_id),
    CONSTRAINT ck_candidates_status CHECK (status IN ('ACTIVE', 'INACTIVE'))
);

-- Entity source: ats_parrent/services/candidate-service/src/main/java/fu/ats/infrastructure/persistence/entity/CandidateSkillEntity.java
-- Unique backing index ux_candidate_skills_candidate_skill: @Table.uniqueConstraints trong CandidateSkillEntity.java
CREATE TABLE candidate_skills (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    candidate_id BIGINT NOT NULL,
    skill_id BIGINT NOT NULL,
    level VARCHAR(20),
    years_exp INTEGER,
    CONSTRAINT pk_candidate_skills PRIMARY KEY (id),
    CONSTRAINT ux_candidate_skills_candidate_skill UNIQUE (candidate_id, skill_id),
    CONSTRAINT fk_candidate_skills_candidate_id FOREIGN KEY (candidate_id) REFERENCES candidates (id)
);

-- Entity source: ats_parrent/services/candidate-service/src/main/java/fu/ats/infrastructure/persistence/entity/CvEntity.java
CREATE TABLE cvs (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    candidate_id BIGINT NOT NULL,
    file_path VARCHAR(1000),
    file_type VARCHAR(50),
    size_bytes BIGINT,
    parsed_data JSONB,
    parse_status VARCHAR(50),
    uploaded_at TIMESTAMPTZ,
    CONSTRAINT pk_cvs PRIMARY KEY (id),
    CONSTRAINT ck_cvs_parse_status CHECK (parse_status IN ('PENDING', 'PARSED', 'FAILED')),
    CONSTRAINT fk_cvs_candidate_id FOREIGN KEY (candidate_id) REFERENCES candidates (id)
);

-- Đề xuất từ relationship: CvEntity.candidate @ManyToOne/@JoinColumn: hỗ trợ JOIN nội bộ và tải collection mappedBy phía parent.
CREATE INDEX idx_cvs_candidate_id ON cvs (candidate_id);

COMMIT;
